def calc(expr: str) -> int | str:
    def parse_int(s: str) -> int:
        if len(s) <= 500:
            return int(s)
        res = 0
        for start in range(0, len(s), 500):
            chunk = s[start:start + 500]
            res = res * (10 ** len(chunk)) + int(chunk)
        return res

    tokens: list[int | str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(parse_int(expr[i:j]))
            i = j
        else:
            tokens.append(ch)
            i += 1

    m = len(tokens)
    pos = 0

    def ipow(base: int, exp: int) -> int:
        if exp < 0:
            raise ZeroDivisionError
        if base == 0:
            return 1 if exp == 0 else 0
        if base == 1:
            return 1
        if base == -1:
            return -1 if (exp & 1) else 1
        return base ** exp

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while pos < m and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_factor()
        while pos < m and tokens[pos] in ("*", "/", "%"):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            if op == "*":
                val *= rhs
            elif op == "/":
                if rhs == 0:
                    raise ZeroDivisionError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            else:
                if rhs == 0:
                    raise ZeroDivisionError
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
        return val

    def parse_factor() -> int:
        nonlocal pos
        neg = False
        while pos < m and tokens[pos] == "-":
            neg = not neg
            pos += 1
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        base = parse_atom()
        if pos >= m or tokens[pos] != "^":
            return base
        chain: list[tuple[bool, int]] = [(False, base)]
        while pos < m and tokens[pos] == "^":
            pos += 1
            neg = False
            while pos < m and tokens[pos] == "-":
                neg = not neg
                pos += 1
            chain.append((neg, parse_atom()))
        val = chain[-1][1]
        if chain[-1][0]:
            val = -val
        for idx in range(len(chain) - 2, -1, -1):
            neg, b = chain[idx]
            val = ipow(b, val)
            if neg:
                val = -val
        return val

    def parse_atom() -> int:
        nonlocal pos
        tok = tokens[pos]
        if isinstance(tok, int):
            pos += 1
            return tok
        pos += 1
        val = parse_expr()
        pos += 1
        return val

    try:
        return parse_expr()
    except ZeroDivisionError:
        return "error"
